#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int m = n - 1;
    int *head = calloc(n + 2, sizeof(int));
    int *nxt = malloc((2 * m + 2) * sizeof(int));
    int *to = malloc((2 * m + 2) * sizeof(int));
    for (int i = 0; i <= n; i++) head[i] = -1;
    for (int i = 0; i < m; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        to[2 * i] = b;     nxt[2 * i] = head[a];     head[a] = 2 * i;
        to[2 * i + 1] = a; nxt[2 * i + 1] = head[b]; head[b] = 2 * i + 1;
    }

    int *parent = calloc(n + 1, sizeof(int));
    int *order = malloc((n + 1) * sizeof(int));
    char *visited = calloc(n + 1, sizeof(char));
    int cnt = 0;
    int *stack = malloc((n + 1) * sizeof(int));
    int top = 0;
    stack[top++] = 1;
    visited[1] = 1;
    parent[1] = 0;
    while (top > 0) {
        int u = stack[--top];
        order[cnt++] = u;
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (!visited[v]) {
                visited[v] = 1;
                parent[v] = u;
                stack[top++] = v;
            }
        }
    }

    long long *sz = calloc(n + 1, sizeof(long long));
    for (int i = 0; i < n; i++) sz[i + 1] = 1;
    for (int i = cnt - 1; i >= 0; i--) {
        int u = order[i];
        if (parent[u] != 0) sz[parent[u]] += sz[u];
    }

    long long best = -1;
    for (int v = 2; v <= n; v++) {
        if (parent[v] != 0 || v == 1) {
            long long s = sz[v];
            long long diff = s * 2 > n ? s * 2 - n : n - s * 2;
            if (best < 0 || diff < best) best = diff;
        }
    }
    /* iterate over edges: each non-root vertex v has one edge to parent */
    best = -1;
    for (int v = 1; v <= n; v++) {
        for (int e = head[v]; e != -1; e = nxt[e]) {
            int u = to[e];
            /* consider edge (v,u): component containing u when removed */
            /* size of component containing child = sz[child] */
        }
    }
    /* simpler: for each vertex except root, edge to parent */
    best = -1;
    for (int v = 2; v <= n; v++) {
        if (parent[v] != 0 || sz[v] < n) {
            long long s = sz[v];
            if (s >= 1 && s <= n - 1) {
                long long diff = n - 2 * s;
                if (diff < 0) diff = -diff;
                if (best < 0 || diff < best) best = diff;
            }
        }
    }

    printf("%lld\n", best);
    return 0;
}
